---
import type { HTMLAttributes } from "astro/types"

import { cn } from "@/lib/utils"

import NavigationMenuPositioner from "./navigation-menu-positioner.astro"

type Props = HTMLAttributes<"nav"> & {
  mountStrategy?: "lazy" | "eager"
  delayOpen?: number
  delayClose?: number
  openOnFocus?: boolean
  side?: "top" | "right" | "bottom" | "left"
  align?: "start" | "center" | "end"
  sideOffset?: number
  alignOffset?: number
  positionMethod?: "absolute" | "fixed"
  safeTriangle?: boolean
  debugSafeTriangle?: boolean
}

const {
  mountStrategy,
  class: className = "",
  delayOpen = 0,
  delayClose = 0,
  openOnFocus,
  side = "bottom",
  align = "start",
  sideOffset = 8,
  alignOffset = 0,
  positionMethod = "absolute",
  safeTriangle,
  debugSafeTriangle,
  "aria-label": ariaLabel = "Main",
  ...props
} = Astro.props
---

<nav
  {...props}
  aria-label={ariaLabel}
  data-slot="navigation-menu"
  data-mount-strategy={mountStrategy}
  data-delay-open={delayOpen}
  data-delay-close={delayClose}
  data-open-on-focus={openOnFocus}
  data-side={side}
  data-align={align}
  data-side-offset={sideOffset}
  data-align-offset={alignOffset}
  data-position-method={positionMethod}
  data-safe-triangle={safeTriangle}
  data-debug-safe-triangle={debugSafeTriangle}
  class={cn(
    "max-w-max group/navigation-menu relative flex flex-1 items-center justify-center",
    className
  )}
>
  <slot />
  <NavigationMenuPositioner {side} {sideOffset} {align} {alignOffset} />
</nav>

<script>
  import { create } from "@data-slot/navigation-menu"

  const controllers: ReturnType<typeof create> = []
  const initialize = () => controllers.push(...create())
  initialize()
  document.addEventListener("astro:page-load", initialize)
  document.addEventListener("astro:before-swap", () => {
    for (const controller of controllers) controller.destroy()
    controllers.length = 0
  })
</script>

