  alignOffset?: number
  side?: "top" | "right" | "bottom" | "left"
  sideOffset?: number
}

const {
  class: className,
  value,
  align,
  alignOffset,
  side,
  sideOffset,
  ...props
} = Astro.props
---

<li
  data-slot="navigation-menu-item"
  data-value={value}
